    #[test]
    fn already_real_returns_equal() {
        let a = vec![
            Complex { re: 1, im: 0 },
            Complex { re: -5, im: 0 },
        ];
        assert_eq!(real_if_close(a.clone(), 1), a);
    }

    #[test]
    fn all_close_zeros_imag() {
        let a = vec![
            Complex { re: 1, im: 2 },   // |2| <= 1*2
            Complex { re: 7, im: -1 },  // |-1| <= 1*2
        ];
        let out = real_if_close(a, 1);
        assert_eq!(out, vec![Complex { re: 1, im: 0 }, Complex { re: 7, im: 0 }]);
    }

    #[test]
